_SANS_B = (0x1D5D4, 0x1D5EE, 0x1D7EC)
_SC_TAB = str.maketrans("abcdefghijklmnopqrstuvwxyz",
                        "ᴀʙᴄᴅᴇꜰɢʜɪᴊᴋʟᴍɴᴏᴘǫʀꜱᴛᴜᴠᴡxʏᴢ")


def _xf(t, spec):
    up, lo, dg = spec
    out = []
    for ch in str(t):
        o = ord(ch)
        if 65 <= o <= 90:
            out.append(chr(up + o - 65))
        elif 97 <= o <= 122:
            out.append(chr(lo + o - 97))
        elif 48 <= o <= 57 and dg:
            out.append(chr(dg + o - 48))
        else:
            out.append(ch)
    return "".join(out)


def sb(t):   return _xf(t, _SANS_B)                # 𝗔𝗕𝗖 bold sans
def sc(t):   return str(t).translate(_SC_TAB)      # ᴀʙᴄ small caps


