def parse_duration(value: str) -> Optional[int]:
    """Parse 30s, 5m, 2h, 1d or a plain number of minutes."""
    match = re.fullmatch(r"\s*(\d+)\s*([smhd]?)\s*", value or "", re.I)
    if not match:
        return None
    amount = int(match.group(1))
    unit = match.group(2).lower() or "m"
    multiplier = {"s": 1, "m": 60, "h": 3600, "d": 86400}[unit]
    return max(1, amount * multiplier)


def format_remaining(seconds: int) -> str:
    seconds = max(0, int(seconds))
    if seconds >= 86400:
        return f"{seconds // 86400}d"
    if seconds >= 3600:
        return f"{seconds // 3600}h"
    if seconds >= 60:
        return f"{seconds // 60}m"
    return f"{seconds}s"


class _HealthHandler(BaseHTTPRequestHandler):
    """Tiny no-dependency health endpoint for hosts that expect an HTTP port."""

    def do_GET(self):
        body = b"nik bot online\n"
        self.send_response(200)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, *_args):
        return


def start_keep_alive() -> None:
    """Start an optional health server; it does not replace a real deployment."""
    port_raw = os.getenv("PORT") or os.getenv("KEEPALIVE_PORT")
    if not port_raw:
        return
    try:
        port = int(port_raw)
        server = ThreadingHTTPServer(("0.0.0.0", port), _HealthHandler)
        threading.Thread(target=server.serve_forever, daemon=True).start()
        log.info("🌐 Health endpoint listening on port %d", port)
    except Exception as exc:
        log.warning("Health endpoint disabled: %s", exc)

