def _get_clock_emoji() -> str:
    """Random emoji picker — now all emojis can be used."""
    return random.choice(CLOCK_EMOJIS)


def fmt_time(template: str, target: str) -> str:
    now   = datetime.datetime.now()
    h     = now.hour % 12 or 12          # 1-12, no leading zero
    m     = now.strftime("%M")
    s     = now.strftime("%S")
    time_str = f"{{ {h}:{m}:{s} }}"      # e.g.  { 6:56:24 }
    clock = _get_clock_emoji()
    emoji = _get_clock_emoji()
    return (
        template
        .replace("{target}", target)
        .replace("{time}",   time_str)
        .replace("{clock}",  clock)
        .replace("{emoji}",  emoji)
    )


