def gen_crash() -> str:
    base  = random.choice(CRASH_LINES)
    extra = "".join(random.choices(string.ascii_letters + string.punctuation, k=500))
    return (base + extra)[:4096]


def fmt(template: str, target: str) -> str:
    return (
        template
        .replace("{target}", target)
        .replace("{Target}", target)
        .replace("{#TARGET}", target)
    )


# ═══════════════════════════════════════════════════════════
#   CONFIG — only loop_delay and gameover_image are saved
#   to config.json at runtime (tokens/owner are hardcoded)
# ═══════════════════════════════════════════════════════════

CONFIG_FILE = Path(__file__).with_name("config.json")


def load_runtime_config() -> dict[str, Any]:
    defaults = {
        "loop_delay":        LOOP_DELAY,
        "gameover_image":    GAMEOVER_IMG,
        "menu_pic":          None,
        "menu_pic_type":     "photo",
        "gameover_pic":      None,        # Telegram file_id — persists across restarts
        "gameover_pic_type": "photo",
    }

    if CONFIG_FILE.exists():
        try:
            with CONFIG_FILE.open(encoding="utf-8") as fh:
                saved = json.load(fh)

            defaults["loop_delay"]      = float(saved.get("loop_delay", defaults["loop_delay"]))
            defaults["gameover_image"]  = str(saved.get("gameover_image", defaults["gameover_image"]))
            defaults["menu_pic"]        = saved.get("menu_pic")
            defaults["menu_pic_type"]   = saved.get("menu_pic_type",   "photo")
            defaults["gameover_pic"]    = saved.get("gameover_pic")         # ← load saved file_id
            defaults["gameover_pic_type"] = saved.get("gameover_pic_type", "photo")

        except Exception:
            pass

    return defaults


def save_runtime_config(
    loop_delay: float,
    gameover_image: str,
    menu_pic=None,
    menu_pic_type: str = "photo",
    gameover_pic=None,           # ← file_id string or None
    gameover_pic_type: str = "photo",
) -> None:

    CONFIG_FILE.write_text(
        json.dumps({
            "loop_delay":        loop_delay,
            "gameover_image":    gameover_image,
            "menu_pic":          menu_pic,
            "menu_pic_type":     menu_pic_type,
            "gameover_pic":      gameover_pic,       # ← persisted
            "gameover_pic_type": gameover_pic_type,
        }, indent=2),
        encoding="utf-8",
    )


