# ═══════════════════════════════════════════════════════════
#   HELPERS
# ═══════════════════════════════════════════════════════════

def is_auth(uid: int) -> bool:
    return uid == OWNER_ID or uid in sudo_users


def pool() -> list[Bot]:
    return [b for b in bots if b]


def arg(update: Update) -> str:
    txt   = update.message.text or ""
    parts = txt.split(None, 1)
    return parts[1].strip() if len(parts) > 1 else ""


def pick_bot(counter: list) -> Optional[Bot]:
    p = pool()
    if not p:
        return None
    b = p[counter[0] % len(p)]
    counter[0] += 1
    return b


async def _pin_message(cid: int, message_id: int, bot: Optional[Bot] = None) -> bool:
    """Pin a message when ~autopin is enabled for the chat."""
    if cid not in autopin_chats:
        return False
    candidates = [bot] if bot else []
    candidates += [b for b in pool() if b is not bot]
    for candidate in candidates:
        if not candidate:
            continue
        try:
            await candidate.pin_chat_message(
                cid, message_id, disable_notification=True
            )
            return True
        except TelegramError:
            continue
    return False


async def _send_bot_message(bot: Bot, cid: int, text: str, **kwargs):
    """Send a managed-bot message and pin it immediately when requested."""
    message = await bot.send_message(cid, text, **kwargs)
    await _pin_message(cid, message.message_id, bot)
    return message


async def _http_get_json(url: str) -> Any:
    def _get() -> Any:
        req = urllib.request.Request(
            url,
            headers={"User-Agent": "nik-bot"},
        )
        with urllib.request.urlopen(req, timeout=25) as response:
            return json.loads(response.read().decode("utf-8"))

    return await asyncio.to_thread(_get)


async def _set_all_bot_profile(method_name: str, **kwargs) -> tuple[int, int, str]:
    success = 0
    failed = 0
    last_error = ""
    for bot in pool():
        method = getattr(bot, method_name, None)
        if not method:
            failed += 1
            last_error = f"installed python-telegram-bot lacks {method_name}"
            continue
        try:
            await method(**kwargs)
            success += 1
        except Exception as exc:
            failed += 1
            last_error = str(exc)
    return success, failed, last_error


async def _bot_description_loop_worker(interval: int, descriptions: list[str]) -> None:
    index = 0
    try:
        while True:
            await _set_all_bot_profile(
                "set_my_description",
                description=descriptions[index % len(descriptions)],
            )
            index += 1
            await asyncio.sleep(interval)
    except asyncio.CancelledError:
        raise


async def try_rename(cid: int, name: str) -> bool:
    for b in pool():
        try:
            await b.set_chat_title(cid, name)
            return True
        except TelegramError:
            pass
    return False


def cancel(tasks: dict[int, asyncio.Task], cid: int) -> bool:
    t = tasks.pop(cid, None)
    if t and not t.done():
        t.cancel()
        return True
    return False


def cancel_all(cid: int) -> list:
    stopped = []
    if cancel(nc_tasks,          cid): stopped.append("NC loop")
    if cancel(spam_tasks,        cid): stopped.append("Spam loop")
    if cancel(slide_tasks,       cid): stopped.append("TargetSlide loop")
    if cancel(picraid_tasks,     cid): stopped.append("PicRaid loop")
    if cancel(crashnc_tasks,     cid): stopped.append("CrashNC")
    if cancel(crashnc2_tasks,    cid): stopped.append("CrashNC2")
    if cancel(crashnc3_tasks,    cid): stopped.append("CrashNC3")
    if swipe_active.pop(cid, None) is not None: stopped.append("Swipe reply")
    if cancel(ftnc_tasks,        cid): stopped.append("FTNC rename")
    if react_config.pop(cid, None) is not None: stopped.append("Auto-React")
    return stopped


def _make_request() -> HTTPXRequest:
    """HTTPXRequest — optimized for low-latency, high-throughput rename ops."""
    return HTTPXRequest(
        connection_pool_size=256,     # larger pool = less waiting for free connections
        connect_timeout=10.0,         # fail fast on dead connections
        read_timeout=20.0,            # shorter read timeout = less ping bloat
        write_timeout=60.0,
    )


async def load_bots(tokens: list) -> list:
    result = []
    for tok in tokens:
        tok = tok.strip()
        if not tok:
            continue
        try:
            b  = Bot(tok, request=_make_request())
            me = await b.get_me()
            result.append(b)
            log.info("✅ Bot loaded: @%s", me.username)
        except TelegramError as e:
            log.error("❌ Token ...%s failed: %s", tok[-6:], e)
    return result


# ═══════════════════════════════════════════════════════════
#   LOOP WORKERS
# ═══════════════════════════════════════════════════════════

async def _rush_bot_rename(bot: Bot, cid: int, name_fn, active: list,
                           stagger: float = 0.0) -> None:
    """Single-bot rename stream — adaptive backoff on flood, max 5s.
    After serving Telegram's mandatory RetryAfter wait, reset delay to BASE
    so we immediately run at full speed again — no extra penalty on top."""
    if stagger:
        await asyncio.sleep(stagger)
    BASE_DELAY   = 0.05            # 50ms base — stable sweet-spot
    MAX_DELAY    = 5.0             # self-imposed cap: max 5s per flood event
    delay        = BASE_DELAY
    clean_streak = 0
    while active[0]:
        try:
            await bot.set_chat_title(cid, name_fn())
            await asyncio.sleep(delay)
            clean_streak += 1
            if clean_streak >= 3 and delay > BASE_DELAY:
                delay        = max(BASE_DELAY, delay * 0.5)
                clean_streak = 0
        except RetryAfter as e:
            wait         = e.retry_after
            clean_streak = 0
            await asyncio.sleep(min(wait, MAX_DELAY))  # serve Telegram wait, cap 5s
            delay = BASE_DELAY                          # reset — fresh 50ms after flood
        except BadRequest:
            await asyncio.sleep(0.5)
        except asyncio.CancelledError:
            break
        except Exception:
            await asyncio.sleep(0.5)


async def _rush_bot_spam(bot: Bot, cid: int, text_fn, active: list,
                         stagger: float = 0.0) -> None:
    """Single-bot spam stream — 0-delay when clean, adaptive backoff on flood.
    On RetryAfter: grow delay (cap 5s). After 5 clean sends: halve back to 0."""
    if stagger:
        await asyncio.sleep(stagger)
    delay        = 0.0
    clean_streak = 0
    while active[0]:
        try:
            await _send_bot_message(bot, cid, text_fn())
            await asyncio.sleep(0)          # yield to event loop, no real wait
            clean_streak += 1
            if clean_streak >= 5 and delay > 0.0:
                delay        = max(0.0, delay * 0.5)
                clean_streak = 0
        except RetryAfter as e:
            wait         = e.retry_after
            delay        = min(delay * 1.5 + wait, 5.0)
            clean_streak = 0
            await asyncio.sleep(wait)
        except asyncio.CancelledError:
            break
        except Exception:
            await asyncio.sleep(0.1)


async def _nc_launcher(cid: int, name_fn) -> None:
    """Launch RENAME_STREAMS independent rename streams per bot — all bots, full speed."""
    active = [True]
    bots_to_use = pool()
    streams = RENAME_STREAMS
    subs = [
        asyncio.create_task(_rush_bot_rename(
            b, cid, name_fn, active,
            stagger=(i * streams + j) * 0.01
        ))
        for i, b in enumerate(bots_to_use)
        for j in range(streams)
    ]
    try:
        await asyncio.gather(*subs)
    except asyncio.CancelledError:
        active[0] = False
        for t in subs:
            t.cancel()
        await asyncio.gather(*subs, return_exceptions=True)
        raise


_LONG_NL: str = "\n" * 15   # 15 blank lines — makes name tall without adding width

def _pad(text: str) -> str:
    """Append newlines so the group name is vertically long (not horizontally wide)."""
    return text + _LONG_NL


async def _worker_nc(cid: int, target: str, bank: list, god: bool = False) -> None:
    txt_cycle = itertools.cycle(bank)
    def _name():
        return _pad(fmt(next(txt_cycle), target))
    await _nc_launcher(cid, _name)


async def _worker_raidnc(cid: int, target: str) -> None:
    txt_cycle = itertools.cycle(RAID_NC_TEXT)
    def _name():
        return _pad(fmt(next(txt_cycle), target))
    await _nc_launcher(cid, _name)


async def _worker_longnc(cid: int, target: str) -> None:
    """Cycles through ALL long NC lines — LONG_NC_TEXTS (𓂃☼ pattern) +
    LONG_NC_LINES (𒈙 pattern) combined into one infinite cycle."""
    txt_cycle = itertools.cycle(LONG_NC_TEXTS + LONG_NC_LINES)
    def _name() -> str:
        return fmt(next(txt_cycle), target)
    await _nc_launcher(cid, _name)


async def _worker_crashnc(cid: int, target: str) -> None:
    import random as _rnd
    def _name():
        e = _rnd.choice(CRASH_EMOJIS)
        return f"{target} {e} {CRASH_BASE}"
    await _nc_launcher(cid, _name)


async def _worker_spam(cid: int, target: str) -> None:
    """All bots spam concurrently — adaptive flood backoff via _rush_bot_spam."""
    def _text() -> str:
        return fmt(SPAM_TEXT, target)

    active      = [True]
    bots_to_use = pool()
    if not bots_to_use:
        return
    subs = [
        asyncio.create_task(
            _rush_bot_spam(b, cid, _text, active, stagger=i * 0.02)
        )
        for i, b in enumerate(bots_to_use)
    ]
    try:
        await asyncio.gather(*subs)
    except asyncio.CancelledError:
        active[0] = False
        for t in subs:
            t.cancel()
        await asyncio.gather(*subs, return_exceptions=True)
        raise


