async def cmd_picraid(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id): return
    cid = update.effective_chat.id

    if update.message.reply_to_message and update.message.reply_to_message.photo:
        import io as _io
        photo = update.message.reply_to_message.photo[-1]
        try:
            f    = await photo.get_file()
            buf  = _io.BytesIO()
            await f.download_to_memory(buf)
            raid_pic[cid] = buf.getvalue()
            await update.message.reply_text(
                "🖼️ *Photo saved!*\nUse `~picraid` again to start GC DP raid.",
                parse_mode="Markdown",
            )
        except Exception as e:
            await update.message.reply_text(f"❌ Download failed: {e}")
        return

    if cid not in raid_pic:
        await update.message.reply_text(
            "❌ No photo saved.\nReply to any photo with `~picraid` to save it first.",
            parse_mode="Markdown",
        )
        return

    cancel(picraid_tasks, cid)
    picraid_tasks[cid] = asyncio.create_task(_worker_picraid(cid, raid_pic[cid]))
    await update.message.reply_text(
        f"🖼️ *PFP RAID* started!\n🤖 Bots: `{len(pool())}`\n_Sab bots GC ka DP change karte rahenge._",
        parse_mode="Markdown",
    )


