async def handle_hosting_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not is_main_bot(ctx):
        return
    """Handle inline button presses on the hosting control panel."""
    query = update.callback_query
    if not query or not query.data: return
    uid = query.from_user.id
    if not is_auth(uid):
        await query.answer("⛔ Sirf owner/sudo use kar sakta hai!", show_alert=True)
        return

    await query.answer()
    action = query.data[len("h:"):]   # strip "h:" prefix

    # ── Add Tokens ──────────────────────────────────────────────────────────
    if action == "addtokens":
        await query.message.reply_text(
            "╭━━━〔 ➕ *𝐓ᴏᴋᴇɴ ᴀᴅᴅ ᴋᴀʀɴᴀ* 〕━━━╮\n\n"
            "┃ *𝐓ᴀʀɪQᴀ ①* — *𝐏ʀɪᴠᴀᴛᴇ ᴄʜᴀᴛ* _(aasaan)_\n"
            "┃ Is bot ko private mein sirf token bhejo\n\n"
            "┃ *𝐓ᴀʀɪQᴀ ②* — *𝐂ᴏᴍᴍᴀɴᴅ*\n"
            "┃ `~addtokens <token1> <token2> ...`\n\n"
            "┃ _Comma ya space se alag karo._\n"
            "┃ _Quotes ki zaroorat nahi._\n"
            "╰━━━━━━━━━━━━━━━━━━━━━━╯",
            parse_mode="Markdown",
        )

    # ── Remove Tokens ───────────────────────────────────────────────────────
    elif action == "removetokens":
        await query.message.reply_text(
            "╭━━━〔 🗑️ *𝐓ᴏᴋᴇɴ ʀᴇᴍᴏᴠᴇ ᴋᴀʀɴᴀ* 〕━━━╮\n\n"
            "┃ *Step 1* — Number dekho:\n"
            "┃ `~listbots`\n\n"
            "┃ *Step 2* — Remove karo:\n"
            "┃ `~removetokens <number>`\n\n"
            "┃ ⚠️ _Main bot (no. 1) remove nahi hoga._\n"
            "╰━━━━━━━━━━━━━━━━━━━━━━╯",
            parse_mode="Markdown",
        )

    # ── List Bots ────────────────────────────────────────────────────────────
    elif action == "listbots":
        lines = [
            "╭━━━〔 🤖 *𝐇ᴏsᴛᴇᴅ ʙᴏᴛs* 〕━━━╮",
            "",
        ]
        for i, b in enumerate(bots, 1):
            label = "🏠 *Main*" if i == 1 else f"➕ Bot {i}"
            try:
                me = await b.get_me()
                lines.append(f"┃ `{i}.` {label}: @{me.username}")
            except Exception:
                lines.append(f"┃ `{i}.` {label}: ❌ offline")
        lines += ["", f"┃ 📊 Total: `{len(bots)}` bots", "╰━━━━━━━━━━━━━━━━━━━━━━╯"]
        await query.message.reply_text("\n".join(lines), parse_mode="Markdown")

    # ── List GCs ─────────────────────────────────────────────────────────────
    elif action == "listgc":
        if not known_chats:
            await query.message.reply_text(
                "╭━━━〔 💬 *𝐆ʀᴏᴜᴘs* 〕━━━╮\n"
                "┃  💤 Koi known GC nahi hai abhi.\n"
                "╰━━━━━━━━━━━━━━━━╯",
                parse_mode="Markdown",
            )
        else:
            lines = [f"╭━━━〔 💬 *𝐊ɴᴏᴡɴ ɢʀᴏᴜᴘ ᴄʜᴀᴛs* (`{len(known_chats)}` total) 〕━━━╮", ""]
            for i, cid in enumerate(sorted(known_chats), 1):
                active = []
                if cid in nc_tasks:      active.append("NC")
                if cid in spam_tasks:    active.append("Spam")
                if cid in picraid_tasks: active.append("PicRaid")
                status_str = f"⚡ {', '.join(active)}" if active else "💤 idle"
                lines.append(f"┃ `{i}.` `{cid}` — {status_str}")
            lines.append("╰━━━━━━━━━━━━━━━━━━━━━━╯")
            await query.message.reply_text("\n".join(lines), parse_mode="Markdown")

    # ── Multimode toggle ─────────────────────────────────────────────────────
    elif action == "multimode":
        if uid != OWNER_ID:
            await query.message.reply_text(
                "╭━━━〔 ⛔ *𝐌ᴜʟᴛɪᴍᴏᴅᴇ* 〕━━━╮\n"
                "┃  Sirf owner toggle kar sakta hai!\n"
                "╰━━━━━━━━━━━━━━━━╯",
                parse_mode="Markdown",
            )
            return
        global MULTIMODE
        MULTIMODE = not MULTIMODE
        state = "🟢 ON" if MULTIMODE else "🔴 OFF"
        await query.message.reply_text(
            f"╭━━━〔 📡 *𝐌ᴜʟᴛɪᴍᴏᴅᴇ {state}* 〕━━━╮\n"
            f"┃  💬 Known GCs: `{len(known_chats)}`\n"
            + (
                "┃  _Ab kisi bhi GC mein command do — sab mein chalegi!_\n"
                if MULTIMODE else
                "┃  _Commands sirf current GC mein chalenge._\n"
            )
            + "╰━━━━━━━━━━━━━━━━╯",
            parse_mode="Markdown",
        )
        # Update the button label on the original menu
        try:
            await query.edit_message_reply_markup(reply_markup=_hosting_keyboard())
        except TelegramError:
            pass

    # ── Status ───────────────────────────────────────────────────────────────
    elif action == "status":
        online_count = 0
        bot_lines    = []
        for i, b in enumerate(bots, 1):
            try:
                me = await b.get_me()
                online_count += 1
                bot_lines.append(f"┃   {'🏠' if i == 1 else '➕'} Bot {i}: @{me.username}")
            except Exception:
                bot_lines.append(f"┃   ❌ Bot {i}: offline")

        total_active = len(set(
            list(nc_tasks.keys()) + list(spam_tasks.keys()) +
            list(slide_tasks.keys()) + list(picraid_tasks.keys()) +
            list(crashnc_tasks.keys())
        ))

        lines = [
            "╭━━━〔 📊 *𝐋ɪᴠᴇ sᴛᴀᴛᴜs* 〕━━━╮", "",
            f"┃ 🟢 Online      : `{online_count}` / `{len(bots)}` bots",
            f"┃ ➕ Extra bots  : `{len(load_dynamic_tokens())}`",
            f"┃ 💬 Known GCs   : `{len(known_chats)}`",
            f"┃ ⚡ Active tasks: `{total_active}` GCs",
            f"┃ 📡 Multimode   : {'🟢 ON' if MULTIMODE else '🔴 OFF'}",
        ] + bot_lines + ["╰━━━━━━━━━━━━━━━━━━━━━━╯"]
        await query.message.reply_text("\n".join(lines), parse_mode="Markdown")

    # ── Shutdown ─────────────────────────────────────────────────────────────
    elif action == "shutdown":
        if uid != OWNER_ID:
            await query.message.reply_text(
                "╭━━━〔 ⛔ *𝐒ʜᴜᴛᴅᴏᴡɴ* 〕━━━╮\n"
                "┃  Sirf owner shutdown kar sakta hai!\n"
                "╰━━━━━━━━━━━━━━━━╯",
                parse_mode="Markdown",
            )
            return
        for cid in list(known_chats) + list(nc_tasks.keys()) + list(spam_tasks.keys()):
            cancel_all(cid)
        nc_tasks.clear(); spam_tasks.clear(); slide_tasks.clear()
        picraid_tasks.clear(); crashnc_tasks.clear()
        crashnc2_tasks.clear(); crashnc3_tasks.clear()
        swipe_active.clear(); purge_chats.clear()
        react_config.clear(); slide_target.clear()
        await query.message.reply_text(
            "╭━━━〔 🛑 *𝐅ᴜʟʟ sʜᴜᴛᴅᴏᴡɴ* 〕━━━╮\n"
            f"┃  ✅ Sab tasks band — `{len(bots)}` bots, sab GCs\n"
            "┃  _Bot ruka nahi — sirf operations stop hue._\n"
            "╰━━━━━━━━━━━━━━━━╯",
            parse_mode="Markdown",
        )

    # ── How To ───────────────────────────────────────────────────────────────
    elif action == "howto":
        await query.message.reply_text(HOWTO_TEXT, parse_mode="Markdown")


    # ── Cluster shortcuts (pehle in buttons ka koi branch hi nahi tha) ──────
    elif action == "joinall":
        await cmd_joinall(_fake_cmd_update(query, "~joinall"), ctx)
    elif action == "broadcast":
        await query.message.reply_text(
            "📣 `~broadcast <message>` — har known GC me ek bot se bhejo.\n"
            "Owner/sudo only.", parse_mode="Markdown"
        )
    elif action == "emojirain":
        await query.message.reply_text(
            "🌧 Kisi message pe *reply* karke `~emojirain` likho — "
            "standard emoji reactions ka rain chalega.", parse_mode="Markdown"
        )

    # ── Access List ──────────────────────────────────────────────────────────
    elif action == "refresh":
        await query.answer("🔄 Refreshed!", show_alert=False)
        try:
            await query.edit_message_reply_markup(reply_markup=_hosting_keyboard())
        except TelegramError:
            pass


