async def cmd_addbots(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~addbots — main bot directly adds + promotes all hosted bots via add_chat_member."""
    if not update.message or not is_auth(update.effective_user.id): return
    cid      = update.effective_chat.id
    p        = pool()
    if not p:
        await update.message.reply_text("❌ Koi bot loaded nahi hai.", parse_mode="Markdown")
        return

    main_bot = p[0]

    prog = await update.message.reply_text(
        "╭━━━〔 🤖 *𝐀𝐝𝐝 𝐁𝐨𝐭𝐬* 〕━━━╮\n"
        "┃  ⏳ Processing...\n"
        "╰━━━━━━━━━━━━━━━━╯",
        parse_mode="Markdown",
    )

    # Collect info for all extra bots (skip main bot — already in group)
    extra_bots_info = []
    for b in p[1:]:
        uname  = "unknown"
        bot_id = 0
        try:
            me     = await b.get_me()
            uname  = f"@{me.username}"
            bot_id = me.id
        except Exception:
            pass
        extra_bots_info.append((uname, bot_id))

    # ── Step 1: Add each bot via main_bot.add_chat_member ─────────────────────
    # Requires main bot to be admin with "Add Members" permission.
    added   = []   # (uname, bot_id) freshly added
    already = []   # (uname, bot_id) already member
    failed  = []   # str descriptions of failures

    for uname, bot_id in extra_bots_info:
        if not bot_id:
            failed.append(f"{uname} — offline")
            continue
        try:
            await main_bot.add_chat_member(cid, bot_id)
            added.append((uname, bot_id))
        except Exception as e:
            err = str(e).lower()
            if any(k in err for k in ("already", "member", "participant")):
                already.append((uname, bot_id))
            elif "deactivated" in err:
                failed.append(f"{uname} — deactivated")
            elif "bot" in err and "added" in err:
                already.append((uname, bot_id))
            else:
                failed.append(f"{uname} — {str(e)[:40]}")
        await asyncio.sleep(0.4)

    # ── Step 2: Promote all (added + already in group) ────────────────────────
    to_promote = added + already
    promoted   = []
    promo_fail = []
    for uname, bot_id in to_promote:
        try:
            await main_bot.promote_chat_member(
                chat_id=cid,
                user_id=bot_id,
                can_change_info=True,
                can_delete_messages=True,
                can_invite_users=True,
                can_restrict_members=True,
                can_pin_messages=True,
                can_manage_chat=True,
                can_manage_video_chats=True,
                can_promote_members=True,
            )
            promoted.append(uname)
        except Exception:
            promo_fail.append(uname)
        await asyncio.sleep(0.2)

    # ── Build premium result panel ────────────────────────────────────────────
    lines = [
        "╭━━━〔 🤖 *𝐀𝐝𝐝 𝐁𝐨𝐭𝐬 𝐑𝐞𝐬𝐮𝐥𝐭* 〕━━━╮",
    ]
    if added:
        lines.append(f"┃ ✅ *Joined ({len(added)}):*")
        for u, _ in added:
            lines.append(f"┃   ╰➤ {u}")
        lines.append("┃")
    if already:
        lines.append(f"┃ 🔁 *Already member ({len(already)}):*")
        for u, _ in already:
            lines.append(f"┃   ╰➤ {u}")
        lines.append("┃")
    if failed:
        lines.append(f"┃ ❌ *Failed ({len(failed)}):*")
        for u in failed:
            lines.append(f"┃   ╰➤ {u}")
        lines.append("┃")
    lines += [
        f"┃ 👑 *Promoted:* `{len(promoted)}` bots",
    ]
    if promo_fail:
        lines.append(f"┃ ⚠️ Promote failed: `{len(promo_fail)}`")
        for u in promo_fail:
            lines.append(f"┃   ╰➤ {u}")
    lines += [
        "┃",
        f"┃ 📊 Total hosted: `{len(p)}`",
    ]
    await prog.edit_text("\n".join(lines), parse_mode="Markdown")


async def cmd_purge(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~purge on/off or ~purge <count> — toggle soft purge or delete recent messages."""
    if not update.message or not is_auth(update.effective_user.id): return
    cid = update.effective_chat.id
    raw = arg(update).lower().strip()

    if raw.isdigit():
        count = max(1, min(int(raw), 100))
        deleted = 0
        for message_id in range(update.message.message_id, update.message.message_id - count, -1):
            for bot in pool():
                try:
                    await bot.delete_message(cid, message_id)
                    deleted += 1
                    break
                except TelegramError:
                    continue
        return

    if raw not in ("on", "off"):
        status = "🟢 ON" if cid in purge_chats else "🔴 OFF"
        await update.message.reply_text(
            f"🗑️ *Purge Mode* : {status}\n"
            f"Usage: `~purge on` / `~purge off` / `~purge 20`",
            parse_mode="Markdown",
        )
        return

    if raw == "on":
        purge_chats.add(cid)
        await update.message.reply_text(
            "🗑️ *Purge ON!*\n_Har naya message delete hota rahega._",
            parse_mode="Markdown",
        )
    else:
        purge_chats.discard(cid)
        await update.message.reply_text(
            "✅ *Purge OFF!*\n_Auto-delete band kar diya._",
            parse_mode="Markdown",
        )


