async def cmd_ping(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id): return

    import time as _time

    t_start = _time.monotonic()

    async def _ping_one(idx: int, b: Bot):
        try:
            t0 = _time.monotonic()
            me = await b.get_me()
            ms = int((_time.monotonic() - t0) * 1000)
            return f"✅ Bot {idx}: @{me.username} — `{ms}ms`", True
        except Exception as e:
            return f"❌ Bot {idx}: offline — `{e}`", False

    results = await asyncio.gather(*[_ping_one(i, b) for i, b in enumerate(bots, 1)])

    lines   = ["📡 *BOT PING STATUS*", ""]
    online  = sum(1 for _, ok in results if ok)
    offline = len(results) - online
    lines  += [line for line, _ in results]
    total_ms = int((_time.monotonic() - t_start) * 1000)
    lines   += [
        "",
        f"🟢 Online : `{online}`",
        f"🔴 Offline: `{offline}`",
        f"📊 Total  : `{len(bots)}`",
        f"⚡ Total  : `{total_ms}ms`",
    ]

    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


async def cmd_uptime(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~uptime — show Nik HEALTH CORE panel with uptime, bots, memory, nodes."""
    if not update.message or not is_auth(update.effective_user.id): return

    import time as _time

    # ── Uptime ────────────────────────────────────────────────────────────────
    delta      = datetime.datetime.now() - BOT_LAUNCH_TIME
    total_secs = int(delta.total_seconds())
    days       = total_secs // 86400
    hours      = (total_secs % 86400) // 3600
    mins       = (total_secs % 3600) // 60
    secs       = total_secs % 60
    uptime_str = f"{days}d {hours}h {mins}m {secs}s"

    # ── Memory (Linux /proc, fallback to resource module) ─────────────────────
    mem_str = "N/A"
    try:
        with open("/proc/self/status") as _f:
            for _line in _f:
                if _line.startswith("VmRSS:"):
                    _kb = int(_line.split()[1])
                    mem_str = f"{_kb // 1024} MB" if _kb >= 1024 else f"{_kb} KB"
                    break
    except Exception:
        try:
            import resource as _res
            _kb = _res.getrusage(_res.RUSAGE_SELF).ru_maxrss
            # Linux = KB, macOS = bytes
            if _kb > 1_000_000:
                _kb //= 1024
            mem_str = f"{_kb // 1024} MB" if _kb >= 1024 else f"{_kb} KB"
        except Exception:
            pass

    # ── Ping every bot (parallel) ─────────────────────────────────────────────
    async def _ping_one(b: Bot):
        try:
            t0 = _time.monotonic()
            me = await b.get_me()
            ms = int((_time.monotonic() - t0) * 1000)
            return me.username, ms, True
        except Exception:
            return None, 0, False

    results = await asyncio.gather(*[_ping_one(b) for b in bots])
    online  = sum(1 for _, _, ok in results if ok)
    total_b = len(bots)
    stability = "100%" if online == total_b else f"{int(online / max(total_b, 1) * 100)}%"
    crashes   = "NONE" if online == total_b else f"{total_b - online} bot(s) down"

    # ── Build node lines ──────────────────────────────────────────────────────
    node_lines = []
    for i, (username, ms, ok) in enumerate(results, 1):
        icon  = "🟢" if ok else "🔴"
        label = f"@{username}" if username else f"bot_{i}"
        ping  = f"{ms}ms" if ok else "offline"
        node_lines.append(f"{icon} ● NODE {i:02d} :: {label}  [{ping}]")
    nodes_text = "\n".join(node_lines) if node_lines else "🔴 ● No bots loaded"

    msg = (
        "╭━━━〔 🐉 NIK • HEALTH CORE 〕━━━╮\n"
        "\n"
        f"🟢 Status    :: ONLINE\n"
        f"🤖 Bots      :: {online}/{total_b} active\n"
        f"⏱ Uptime    :: {uptime_str}\n"
        f"💾 Memory    :: {mem_str}\n"
        "\n"
        "────────── SYSTEM NODES ──────────\n"
        f"{nodes_text}\n"
        "──────────────────────────────────\n"
        "\n"
        f"✅ Stability : {stability}\n"
        f"⚡ Crashes   : {crashes}\n"
        "\n"
        "╰━━━〔 NIK CORE 〕━━━╯"
    )
    await update.message.reply_text(msg)


