async def cmd_broadcast(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    text = arg(update).strip()
    if not text:
        await update.message.reply_text("Usage: `~broadcast <message>`", parse_mode="Markdown")
        return
    msg = await update.message.reply_text("📣 Broadcasting...")
    sent = failed = 0
    for cid in list(known_chats):
        for b in pool():
            try:
                await b.send_message(cid, text)
                sent += 1
                break
            except TelegramError:
                failed += 1
    await msg.edit_text(f"📣 Sent: {sent} GCs · ❌ Failed: {failed}")


async def cmd_emojirain(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~emojirain — standard emoji reactions (no premium custom emoji IDs)."""
    if not update.message or not is_auth(update.effective_user.id):
        return
    target = update.message.reply_to_message
    if not target:
        await update.message.reply_text("Reply to a message for emoji rain ✨")
        return
    for emo in ("🔥", "⚡", "💯", "🎉", "❤️", "👑", "🤯", "😈", "👍", "🥳"):
        try:
            await target.set_reaction([ReactionTypeEmoji(emoji=emo)])
        except TelegramError:
            pass
        await asyncio.sleep(0.3)
    await update.message.reply_text("✨ Emoji rain done!")


