_PLUGIN_TASKS: dict[str, asyncio.Task] = {}


def _plugin_stop(key: str) -> bool:
    t = _PLUGIN_TASKS.pop(key, None)
    if t and not t.done():
        t.cancel()
        return True
    return False


async def cmd_randnc(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Random unpredictable group-name loop (anti-pattern)."""
    if not update.message or not is_auth(update.effective_user.id):
        return
    cid = update.effective_chat.id
    _plugin_stop(f"randnc:{cid}")
    base = arg(update) or "Nik"

    async def _loop():
        while True:
            target = f"{base} {''.join(random.choices(string.ascii_letters + string.digits, k=6))}"
            await _worker_nc(cid, target, pool())
            await asyncio.sleep(0.4)

    _PLUGIN_TASKS[f"randnc:{cid}"] = asyncio.create_task(_loop())
