import html as _html

ADV_PREFIX_FILE  = Path(__file__).with_name("prefix_state.json")
ADV_USERS_FILE   = Path(__file__).with_name("known_users.json")
ADV_SUDO_FILE    = Path(__file__).with_name("sudo_users.json")
PYRO_SESSION_FILE = Path(__file__).with_name("userbot_session.json")
PYRO_API_ID      = int(os.environ.get("PYRO_API_ID", "0") or 0)
PYRO_API_HASH    = (os.environ.get("PYRO_API_HASH", "") or "").strip()


def _jload(path: Path, default):
    try:
        if path.exists():
            obj = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(obj, type(default)):
                return obj
    except Exception:
        pass
    return default


def _jsave(path: Path, obj) -> None:
    try:
        path.write_text(json.dumps(obj, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass


def _esc(value) -> str:
    return _html.escape(str(value if value is not None else ""), quote=False)


def _chunks(text: str, size: int = 3300) -> list[str]:
    out, cur = [], ""
    for line in text.split("\n"):
        while len(line) > size:
            if cur:
                out.append(cur)
                cur = ""
            out.append(line[:size])
            line = line[size:]
        if len(cur) + len(line) + 1 > size:
            out.append(cur)
            cur = line
        else:
            cur = (cur + "\n" + line) if cur else line
    if cur:
        out.append(cur)
    return out or ["—"]


# ── 1. PREFIX TOGGLE ───────────────────────────────────────────────────────
PREFIX_ENABLED: bool = bool(_jload(ADV_PREFIX_FILE, {"enabled": True}).get("enabled", True))


async def prefix_gate(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """group=-2 · jab prefix OFF ho to har ~command block; ~prefix khud hamesha chalega."""
    if PREFIX_ENABLED:
        return
    msg = update.message
    if not msg or not msg.text:
        return
    txt = msg.text.strip()
    if not txt.startswith("~"):
        return
    if re.match(r"(?i)^~prefix\b", txt):
        return
    from telegram.ext import ApplicationHandlerStop
    raise ApplicationHandlerStop


async def cmd_prefix(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~prefix on|off|status — ~ prefix ka master switch."""
    global PREFIX_ENABLED
    if not update.message or update.effective_user.id != OWNER_ID:
        return
    raw = arg(update).strip().lower()
    if raw in ("on", "enable", "1", "yes"):
        PREFIX_ENABLED = True
    elif raw in ("off", "disable", "0", "no"):
        PREFIX_ENABLED = False
    elif raw in ("", "status", "state"):
        pass
    else:
        await update.message.reply_text(
            "Usage: `~prefix on` · `~prefix off` · `~prefix status`",
            parse_mode="Markdown",
        )
        return
    _jsave(ADV_PREFIX_FILE, {"enabled": PREFIX_ENABLED})
    state = "🟢 ON" if PREFIX_ENABLED else "🔴 OFF"
    await update.message.reply_text(
        f"🔣 *~ PREFIX* — {state}\n\n"
        "• ON  → sab `~` commands chalu\n"
        "• OFF → koi bhi `~` command kaam nahi karega\n"
        "• OFF me wapas chalu karne ke liye `~prefix on` (ya `/prefix on`) bhejo\n"
        f"• Owner: `{OWNER_ID}`",
        parse_mode="Markdown",
    )


async def cmd_slash_prefix(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/prefix on|off — escape hatch jab ~ prefix band ho."""
    if not update.message or update.effective_user.id != OWNER_ID:
        return
    raw = (update.message.text or "").split(None, 1)
    tail = raw[1].strip() if len(raw) > 1 else "status"
    global PREFIX_ENABLED
    if tail.lower() in ("on", "enable", "1"):
        PREFIX_ENABLED = True
    elif tail.lower() in ("off", "disable", "0"):
        PREFIX_ENABLED = False
    _jsave(ADV_PREFIX_FILE, {"enabled": PREFIX_ENABLED})
    await update.message.reply_text(
        f"🔣 `~` prefix = {'🟢 ON' if PREFIX_ENABLED else '🔴 OFF'}",
        parse_mode="Markdown",
    )


# ── 2. USER CACHE  (username + id + name) ───────────────────────────────────
# uid(str) -> {"id": int, "name": str, "username": str}
KNOWN_USERS: dict[str, dict] = _jload(ADV_USERS_FILE, {}) or {}
_USER_SAVE_COUNTER = [0]


def _cache_user(u) -> dict | None:
    if not u:
        return None
    uid = getattr(u, "id", None)
    if not uid:
        return None
    info = {
        "id": int(uid),
        "name": " ".join(
            x for x in [
                getattr(u, "first_name", "") or "",
                getattr(u, "last_name", "") or "",
            ] if x
        ).strip(),
        "username": (getattr(u, "username", "") or "").lstrip("@"),
    }
    key = str(uid)
    old = KNOWN_USERS.get(key) or {}
    merged = {**old, **{k: v for k, v in info.items() if v}}
    merged["id"] = int(uid)
    KNOWN_USERS[key] = merged
    _USER_SAVE_COUNTER[0] += 1
    if _USER_SAVE_COUNTER[0] % 15 == 0:
        _jsave(ADV_USERS_FILE, KNOWN_USERS)
    return merged


def _uinfo(uid) -> dict:
    return KNOWN_USERS.get(str(uid)) or {"id": int(uid), "name": "", "username": ""}


def _u3(info: dict) -> str:
    """Name · @username · ID — teenon field."""
    name = _esc(info.get("name") or "—")
    un = (info.get("username") or "").lstrip("@")
    handle = "@" + _esc(un) if un else "—"
    return f"{name} · {handle} · <code>{_esc(info.get('id'))}</code>"


async def _fetch_user(uid: int) -> dict:
    info = dict(_uinfo(uid))
    for b in pool()[:3]:
        try:
            ch = await b.get_chat(uid)
            info["id"] = int(uid)
            info["name"] = (
                " ".join(
                    x for x in [
                        getattr(ch, "first_name", "") or "",
                        getattr(ch, "last_name", "") or "",
                    ] if x
                ).strip() or info.get("name") or ""
            )
            info["username"] = (getattr(ch, "username", "") or "").lstrip("@") or info.get("username", "")
            KNOWN_USERS[str(uid)] = info
            _jsave(ADV_USERS_FILE, KNOWN_USERS)
            break
        except Exception:
            continue
    return info


async def resolve_user(token: str, reply=None) -> dict | None:
    """~sudo ke liye: reply > numeric ID > @username (cache / Bot API / userbot)."""
    if reply is not None and getattr(reply, "from_user", None):
        return _cache_user(reply.from_user)
    raw = (token or "").strip()
    if not raw:
        return None
    if raw.lstrip("@").isdigit():
        return await _fetch_user(int(raw.lstrip("@")))
    uname = raw.lstrip("@").lower()
    for key, val in KNOWN_USERS.items():
        if (val.get("username") or "").lower() == uname:
            return await _fetch_user(int(key))
    for b in pool()[:3]:
        try:
            ch = await b.get_chat("@" + uname)
            info = {
                "id": int(ch.id),
                "name": " ".join(
                    x for x in [
                        getattr(ch, "first_name", "") or "",
                        getattr(ch, "last_name", "") or "",
                    ] if x
                ).strip(),
                "username": (getattr(ch, "username", "") or "").lstrip("@") or uname,
            }
            KNOWN_USERS[str(ch.id)] = info
            _jsave(ADV_USERS_FILE, KNOWN_USERS)
            return info
        except Exception:
            continue
    try:
        cl = await userbot.get_client()
        if cl is not None:
            u = await cl.get_users(uname)
            info = {
                "id": int(u.id),
                "name": " ".join(
                    x for x in [getattr(u, "first_name", "") or "", getattr(u, "last_name", "") or ""] if x
                ).strip(),
                "username": (getattr(u, "username", "") or "").lstrip("@") or uname,
            }
            KNOWN_USERS[str(u.id)] = info
            _jsave(ADV_USERS_FILE, KNOWN_USERS)
            return info
    except Exception:
        pass
    return None


# ── 3. SUDO — id / username / reply ────────────────────────────────────────
def _save_sudo() -> None:
    _jsave(ADV_SUDO_FILE, {"users": sorted(int(x) for x in sudo_users)})


try:
    for _sid in _jload(ADV_SUDO_FILE, {"users": []}).get("users", []):
        sudo_users.add(int(_sid))
except Exception:
    pass


async def cmd_sudo(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~sudo <id> | ~sudo @username | reply + ~sudo"""
    if not update.message or update.effective_user.id != OWNER_ID:
        return
    info = await resolve_user(arg(update), update.message.reply_to_message)
    if not info:
        await update.message.reply_text(
            "❌ User resolve nahi hua.\n"
            "• kisi message pe *reply* karke `~sudo`\n"
            "• `~sudo 123456789`\n"
            "• `~sudo @username`\n\n"
            "_@username tabhi milega jab user ne GC me message kiya ho ya userbot login ho._",
            parse_mode="Markdown",
        )
        return
    uid = int(info["id"])
    if uid == OWNER_ID:
        await update.message.reply_text("👑 Owner pehle se hi full access rakhta hai.")
        return
    already = uid in sudo_users
    sudo_users.add(uid)
    _save_sudo()
    await update.message.reply_text(
        ("♻️ <b>Sudo refreshed</b>\n" if already else "👤 <b>Sudo Added</b>\n")
        + "\n" + _u3(info) + "\n\n📊 Total sudo: <b>" + str(len(sudo_users)) + "</b>",
        parse_mode="HTML",
    )


async def cmd_delsudo(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~delsudo <id> | ~delsudo @username | reply"""
    if not update.message or update.effective_user.id != OWNER_ID:
        return
    info = await resolve_user(arg(update), update.message.reply_to_message)
    if not info:
        await update.message.reply_text(
            "❌ User resolve nahi hua. `~delsudo <id>` / `~delsudo @username` / reply karo.",
            parse_mode="Markdown",
        )
        return
    uid = int(info["id"])
    sudo_users.discard(uid)
    _save_sudo()
    await update.message.reply_text(
        "🚫 <b>Sudo Removed</b>\n\n" + _u3(info),
        parse_mode="HTML",
    )


async def cmd_sudolist(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~sudolist — name · @username · ID (teenon)."""
    if not update.message or not is_auth(update.effective_user.id):
        return
    lines = ["<b>👤 SUDO LIST</b>", ""]
    owner = await _fetch_user(OWNER_ID)
    lines.append(f"👑 <b>OWNER</b> → {_u3(owner)}")
    lines.append("")
    if not sudo_users:
        lines.append("ℹ️ Koi extra sudo nahi hai.")
    else:
        infos = await asyncio.gather(*(_fetch_user(int(u)) for u in sorted(sudo_users)))
        for i, info in enumerate(infos, 1):
            lines.append(f"{i}. {_u3(info)}")
    lines += ["", f"📊 Total sudo: <code>{len(sudo_users)}</code> · owner: <code>1</code>"]
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")


async def cmd_clearsudo(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or update.effective_user.id != OWNER_ID:
        return
    count = len(sudo_users)
    sudo_users.clear()
    _save_sudo()
    await update.message.reply_text(f"🧹 <b>{count}</b> sudo hata diye.", parse_mode="HTML")


