async def handle_panel_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    global PREFIX_ENABLED
    if not is_main_bot(ctx):
        return
    query = update.callback_query
    if not query or not query.data:
        return
    uid = query.from_user.id
    if not is_auth(uid):
        await query.answer("Owner / Sudo only", show_alert=True)
        return
    action = query.data[len("panel:"):]
    await query.answer()
    target = query.message
    if action == "open":
        try:
            await query.edit_message_text(
                advanced_panel_header(), parse_mode="Markdown", reply_markup=panel_keyboard()
            )
        except TelegramError:
            pass
    elif action == "back":
        try:
            await query.edit_message_text(
                hosting_header(), parse_mode="Markdown", reply_markup=_hosting_keyboard()
            )
        except TelegramError:
            pass
    elif action == "refresh":
        try:
            await query.edit_message_text(
                advanced_panel_header(), parse_mode="Markdown", reply_markup=panel_keyboard()
            )
            await query.answer("🔄 Refreshed")
        except TelegramError:
            pass
    elif action == "status":
        await _send_chunks(target, "<b>📊 ʟɪᴠᴇ sᴛᴀᴛᴜs</b>\n\n" + _esc(menu_live_status())
                           + f"\n🔣 prefix: <b>{'ON' if PREFIX_ENABLED else 'OFF'}</b>"
                           + f"\n🔑 userbot: {userbot.state_line()}")
    elif action == "sudo":
        await _send_chunks(target, await build_sudo_report())
    elif action == "gcs":
        await query.answer("🔍 GCs scan…")
        report = await build_gc_report()
        await _send_chunks(target, report)
        await send_owner_report(report)
    elif action == "bots":
        await _send_chunks(target, await build_bot_report())
    elif action == "tasks":
        await _send_chunks(target, await build_task_report())
    elif action == "prefix":
        kb = InlineKeyboardMarkup([[
            InlineKeyboardButton("🟢 ᴏɴ",  callback_data="panel:prefix_on"),
            InlineKeyboardButton("🔴 ᴏꜰꜰ", callback_data="panel:prefix_off"),
        ]])
        await target.reply_text(
            f"🔣 `~` prefix = <b>{'ON 🟢' if PREFIX_ENABLED else 'OFF 🔴'}</b>\n"
            "<i>OFF me bhi ~prefix on chalega.</i>",
            parse_mode="HTML", reply_markup=kb,
        )
    elif action in ("prefix_on", "prefix_off"):
        if uid != OWNER_ID:
            await query.answer("Owner only", show_alert=True)
            return
        PREFIX_ENABLED = action == "prefix_on"
        _jsave(ADV_PREFIX_FILE, {"enabled": PREFIX_ENABLED})
        await query.answer(f"Prefix {'ON' if PREFIX_ENABLED else 'OFF'}")
        try:
            await query.edit_message_text(
                advanced_panel_header(), parse_mode="Markdown", reply_markup=panel_keyboard()
            )
        except TelegramError:
            pass
    elif action == "login":
        await target.reply_text(
            "<b>🔑 ᴜsᴇʀʙᴏᴛ ʟᴏɢɪɴ</b>\n\n" + userbot.state_line()
            + "\n\n<code>~login</code> · <code>~setsession &lt;str&gt;</code> · "
            "<code>~session</code> · <code>~logout</code> · <code>~fjoin &lt;link&gt;</code>",
            parse_mode="HTML",
        )
    elif action == "menu":
        for chunk in menu_chunks():
            try:
                await target.reply_text(chunk, parse_mode="Markdown")
            except Exception:
                pass
    elif action == "owner":
        profiles, metas = await collect_cluster()
        full = "\n\n".join([
            await build_gc_report(profiles, metas),
            await build_bot_report(profiles, metas),
            await build_task_report(profiles, metas),
            await build_sudo_report(),
        ])
        ok = await send_owner_report(full)
        await query.answer("📩 Owner DM me bhej diya" if ok else "❌ DM fail", show_alert=True)


def _fake_cmd_update(query, cmd_text: str):
    """Inline button → command function bridge (text-based arg() ke liye)."""
    real = query.message

    class _Msg:
        text = cmd_text
        reply_to_message = None

        async def reply_text(self, *a, **kw):
            return await real.reply_text(*a, **kw)

        async def edit_text(self, *a, **kw):
            return await real.reply_text(*a, **kw)

    class _Upd:
        message = _Msg()
        effective_user = query.from_user
        effective_chat = real.chat

    return _Upd()


