# ── 1. MAIN BOT GUARD — "baap level" management sirf main bot pe ──────────
MAIN_BOT_ID: int = 0
MAIN_BOT_USERNAME: str = ""

BAAP_COMMANDS: set[str] = {
    "addtokens", "addtoken", "addbots", "removetoken", "removetokens",
    "listbots", "listbot", "multimode", "shutdown", "sudo", "delsudo",
    "sudolist", "clearsudo", "panel", "control", "prefix", "login",
    "setsession", "session", "logout", "fjoin", "joinall", "gcs", "groups",
    "gcdetail", "bots", "botdetail", "tasks", "ownerreport", "stats",
    "status", "listgc", "knownchats", "setdelay", "setbotdescloop", "start",
    "setbotname", "setbotbio", "setbotdesc", "setbotpfp", "setmenu",
    "setmenuvid", "removemenupic", "leaveall", "broadcast", "ui",
}


def is_main_bot(ctx) -> bool:
    """Sirf hosting (main) bot management chala sakta hai."""
    if ctx is None or not MAIN_BOT_ID:
        return True
    try:
        bid = int(getattr(ctx.bot, "id", 0) or 0)
    except Exception:
        bid = 0
    if bid:
        return bid == MAIN_BOT_ID
    if MAIN_BOT_USERNAME:
        try:
            return (getattr(ctx.bot, "username", "") or "").lstrip("@").lower() == MAIN_BOT_USERNAME.lower()
        except Exception:
            pass
    return True


async def main_bot_guard(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """group=-4 · non-main bot pe koi bhi management command block."""
    if is_main_bot(ctx):
        return
    msg = update.message
    if not msg or not msg.text:
        return
    parts = msg.text.strip().split()
    if not parts:
        return
    cmd = parts[0].lstrip("~/").lower().split("@", 1)[0]
    if cmd in BAAP_COMMANDS:
        from telegram.ext import ApplicationHandlerStop
        raise ApplicationHandlerStop


# ── 2. ANIMATED UI KIT (standard Unicode only — koi custom ID nahi) ───────
UI_BARS = ["▱▱▱▱▱", "▰▱▱▱▱", "▰▰▱▱▱", "▰▰▰▱▱", "▰▰▰▰▱", "▰▰▰▰▰"]
UI_SPIN = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"]
UI_FACE = ["🛰", "⚡", "🔮", "🧬", "✅"]


def ui_card(title: str, rows: list[str], footer: str = "ᴍᴀᴅᴇ ʙʏ @Nikkkwa") -> str:
    """Box-drawing card — HTML parse mode ke liye."""
    w = 34
    top = "╭" + "─" * w + "╮"
    sep = "├" + "─" * w + "┤"
    end = "╰" + "─" * w + "╯"
    out = [top, f"┃  {title}", sep]
    out += [f"┃  {r}" for r in rows]
    if footer:
        out += [sep, f"┃  {footer}"]
    out.append(end)
    return "\n".join(out)


async def ui_animate(msg, title: str, target: str, rounds: int = 4,
                     clear_kb: bool = False) -> None:
    """Live progress bar + spinner — message ko edit karke animation."""
    for i in range(max(2, rounds)):
        spin = UI_SPIN[i % len(UI_SPIN)]
        face = UI_FACE[min(i, len(UI_FACE) - 1)]
        bar = UI_BARS[min(int(i / max(1, rounds - 1) * (len(UI_BARS) - 1)), len(UI_BARS) - 1)]
        pct = int((i + 1) / max(2, rounds) * 100)
        text = ui_card(title, [
            f"{face} {spin} <b>ᴡᴏʀᴋɪɴɢ</b> · <code>{pct}%</code>",
            f"<code>[{bar}]</code>",
            f"🎯 {_esc(target)}",
        ])
        kw = {}
        if clear_kb and i == 0:
            kw["reply_markup"] = InlineKeyboardMarkup([])
        try:
            await msg.edit_text(text, parse_mode="HTML", **kw)
        except Exception:
            pass
        await asyncio.sleep(0.42)


async def _ui_dashboard(msg) -> None:
    """Animated live cluster dashboard."""
    profiles = await _bot_profiles()
    live = sum(1 for c in known_chats if tasks_for(c))
    rows_base = [
        f"🤖 ɴᴏᴅᴇs : <b>{len(profiles)}</b> · 💬 ɢᴄs : <b>{len(known_chats)}</b>",
        f"⚡ ʟɪᴠᴇ ᴛᴀsᴋs : <b>{live}</b> · ⏱ {_esc(_uptime_str())}",
        f"🔣 ᴘʀᴇꜰɪx : <b>{'ᴏɴ' if PREFIX_ENABLED else 'ᴏꜰꜰ'}</b> · 🔑 sᴇssɪᴏɴ : <b>{'ᴏɴ' if userbot.session else 'ᴏꜰꜰ'}</b>",
        f"👤 sᴜᴅᴏ : <b>{len(sudo_users)}</b> · 👁 ᴜsᴇʀs : <b>{len(KNOWN_USERS)}</b>",
    ]
    for i in range(5):
        spin = UI_SPIN[i % len(UI_SPIN)]
        face = UI_FACE[min(i, len(UI_FACE) - 1)]
        bar = UI_BARS[min(i, len(UI_BARS) - 1)]
        pct = (i + 1) * 20
        rows = [
            f"{face} {spin} <b>ᴄʟᴜsᴛᴇʀ sᴄᴀɴ</b> · <code>{pct}%</code>",
            f"<code>[{bar}]</code>",
        ] + rows_base
        try:
            await msg.edit_text(ui_card("👑 ɴɪᴋ ʙᴏᴛ · ʟɪᴠᴇ ᴜɪ", rows), parse_mode="HTML")
        except Exception:
            pass
        await asyncio.sleep(0.48)
    try:
        await msg.edit_text(
            ui_card("👑 ɴɪᴋ ʙᴏᴛ · ʟɪᴠᴇ ᴜɪ",
                    ["✅ <b>sᴄᴀɴ ᴄᴏᴍᴘʟᴇᴛᴇ</b>"] + rows_base),
            parse_mode="HTML",
        )
    except Exception:
        pass


