# ── 3. PROFILE ENGINE — group=all · dm=pick · dm=all ──────────────────────
_PROFILE_METHODS: dict[str, tuple[str, str]] = {
    "name": ("set_my_name", "ɴᴀᴍᴇ"),
    "bio":  ("set_my_short_description", "sʜᴏʀᴛ ʙɪᴏ"),
    "desc": ("set_my_description", "ᴅᴇsᴄʀɪᴘᴛɪᴏɴ"),
    "pfp":  ("set_my_profile_photo", "ᴘʀᴏꜰɪʟᴇ ᴘʜᴏᴛᴏ"),
}

# uid -> {"kind": str, "value": str, "ts": float}
_prof_pending: dict[int, dict] = {}
_PROFILE_TTL = 300.0


def _parse_profile_arg(raw: str) -> tuple[str, str]:
    """--all / @username / #2 flags nikaal kar (token, value) return karo."""
    raw = (raw or "").strip()
    if raw == "--all" or raw.startswith("--all "):
        return "all", raw[len("--all"):].strip()
    if raw.startswith("@"):
        parts = raw.split(None, 1)
        return parts[0].lower(), (parts[1].strip() if len(parts) > 1 else "")
    m = re.match(r"^#(\d+)(?:\s+|$)(.*)$", raw, re.S)
    if m:
        return "#" + m.group(1), (m.group(2) or "").strip()
    return "", raw


async def _profile_choices() -> list[dict]:
    return await _bot_profiles()


async def _profile_targets(token: str, profiles: list[dict]):
    if token == "all":
        return [p["bot"] for p in profiles], "🌐 ᴀʟʟ ʙᴏᴛs"
    if token.startswith("@"):
        for p in profiles:
            if (p["username"] or "").lower() == token[1:]:
                return [p["bot"]], "@" + (p["username"] or str(p["id"]))
        return None, None
    if token.startswith("#"):
        idx = int(token[1:]) - 1
        if 0 <= idx < len(profiles):
            p = profiles[idx]
            return [p["bot"]], "@" + (p["username"] or str(p["id"]))
    return None, None


async def _profile_buttons(profiles: list[dict]) -> InlineKeyboardMarkup:
    rows = []
    for i, p in enumerate(profiles[:16], 1):
        label = f"{i}. @{p['username'] or p['id']}" if p["username"] else f"{i}. {p['id']}"
        if not p["online"]:
            label = "🔴 " + label
        rows.append([InlineKeyboardButton(label, callback_data=f"prof:pick:{p['id']}")])
    rows.append([
        InlineKeyboardButton("🌐 ᴀʟʟ ʙᴏᴛs", callback_data="prof:all"),
        InlineKeyboardButton("❌ ᴄᴀɴᴄᴇʟ",   callback_data="prof:cancel"),
    ])
    return InlineKeyboardMarkup(rows)


def ui_result_card(kind: str, results: list[tuple[str, bool, str]], label: str) -> str:
    ok = sum(1 for _, good, _ in results if good)
    field = _PROFILE_METHODS[kind][1]
    rows = [
        f"⚙ ꜰɪᴇʟᴅ  : <b>{field}</b>",
        f"🎯 ᴛᴀʀɢᴇᴛ : {_esc(label)}",
        "",
    ]
    for name, good, err in results[:14]:
        rows.append(
            f"{'✅' if good else '❌'} <code>{_esc(name)}</code>"
            + ("" if good else f" · {_esc(err[:60])}")
        )
    if len(results) > 14:
        rows.append(f"… +{len(results) - 14} more")
    rows += ["", f"📊 <b>{ok}/{len(results)}</b> ᴜᴘᴅᴀᴛᴇᴅ"]
    return ui_card("👑 ɴɪᴋ ʙᴏᴛ · ᴘʀᴏꜰɪʟᴇ ᴇɴɢɪɴᴇ", rows)


async def apply_profile(kind: str, value: str, targets: list) -> list[tuple[str, bool, str]]:
    """Ek ya zyada bots pe name / bio / desc / pfp apply karo."""
    method = _PROFILE_METHODS[kind][0]
    if kind == "name":
        kwargs = {"name": value[:64]}
    elif kind == "bio":
        kwargs = {"short_description": value[:512]}
    elif kind == "desc":
        kwargs = {"description": value[:512]}
    else:
        kwargs = {"photo": {"type": "static", "photo": value}}
    out = []
    for b in targets:
        try:
            me = await b.get_me()
            label = "@" + (getattr(me, "username", "") or str(me.id))
        except Exception:
            label = "?"
        fn = getattr(b, method, None)
        if fn is None:
            out.append((label, False, "method missing"))
            continue
        try:
            await fn(**kwargs)
            out.append((label, True, ""))
        except Exception as exc:
            out.append((label, False, str(exc)[:100]))
    return out


async def _profile_run(msg, kind: str, value: str, targets: list, label: str,
                       clear_kb: bool = False) -> None:
    await ui_animate(msg, "👑 ɴɪᴋ ʙᴏᴛ · ᴘʀᴏꜰɪʟᴇ ᴇɴɢɪɴᴇ", label, 4, clear_kb)
    results = await apply_profile(kind, value, targets)
    text = ui_result_card(kind, results, label)
    try:
        await msg.edit_text(text, parse_mode="HTML")
    except Exception:
        try:
            await msg.reply_text(text, parse_mode="HTML")
        except Exception:
            pass


_PROFILE_USAGE = {
    "name": "`~setbotname <txt>` · `--all` · `#2 <txt>` · `@bot <txt>`",
    "bio":  "`~setbotbio <txt>` · `--all` · `#2 <txt>` · `@bot <txt>`",
    "desc": "`~setbotdesc <txt>` · `--all` · `#2 <txt>` · `@bot <txt>`",
    "pfp":  "Photo pe *reply* karke `~setbotpfp` · `--all` · `#2` · `@bot`",
}


async def _profile_entry(update: Update, ctx, kind: str, value: str, token: str) -> None:
    """Group → sab bots. DM → picker (ya direct flag)."""
    if not update.message or update.effective_user.id != OWNER_ID:
        return
    if not is_main_bot(ctx):
        return
    if kind != "pfp" and not value:
        await update.message.reply_text(
            "❌ " + _PROFILE_USAGE[kind], parse_mode="Markdown"
        )
        return
    profiles = await _profile_choices()
    if not profiles:
        await update.message.reply_text("⚠️ Koi bot loaded nahi hai.")
        return
    chat = update.effective_chat
    in_group = getattr(chat, "type", "") in ("group", "supergroup")

    if token:
        targets, label = await _profile_targets(token, profiles)
        if not targets:
            await update.message.reply_text(
                f"❌ Target `{token}` nahi mila. `~listbots` se index dekho.",
                parse_mode="Markdown",
            )
            return
        msg = await update.message.reply_text("⚡ ...", parse_mode="HTML")
        await _profile_run(msg, kind, value, targets, label)
        return

    if in_group:
        targets = [p["bot"] for p in profiles]
        msg = await update.message.reply_text("⚡ ...", parse_mode="HTML")
        await _profile_run(msg, kind, value, targets, "🌐 ᴀʟʟ ʙᴏᴛs · ɢʀᴏᴜᴘ ᴍᴏᴅᴇ")
        return

    _prof_pending[update.effective_user.id] = {
        "kind": kind, "value": value, "ts": time.time(),
    }
    field = _PROFILE_METHODS[kind][1]
    card = ui_card("👑 ɴɪᴋ ʙᴏᴛ · ᴄʜᴏᴏsᴇ ᴀ ʙᴏᴛ", [
        f"⚙ ꜰɪᴇʟᴅ : <b>{field}</b>",
        f"📍 ᴍᴏᴅᴇ : <b>ᴅᴍ · sɪɴɢʟᴇ ʙᴏᴛ</b>",
        "",
        "┃  Ek bot chuno, ya <b>🌐 ᴀʟʟ ʙᴏᴛs</b> dabao.",
        "┃  Group me bhejne pe apne aap sab bots pe lagega.",
    ])
    await update.message.reply_text(
        card, parse_mode="HTML", reply_markup=await _profile_buttons(profiles)
    )


async def cmd_setbotname(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~setbotname <txt> — group: all bots · DM: pick one / ALL."""
    token, value = _parse_profile_arg(arg(update))
    await _profile_entry(update, ctx, "name", value, token)


async def cmd_setbotbio(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~setbotbio <txt> — short bio."""
    token, value = _parse_profile_arg(arg(update))
    await _profile_entry(update, ctx, "bio", value, token)


async def cmd_setbotdesc(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~setbotdesc <txt> — long description."""
    token, value = _parse_profile_arg(arg(update))
    await _profile_entry(update, ctx, "desc", value, token)


async def cmd_setbotpfp(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~setbotpfp — photo pe reply; group: all · DM: pick / ALL."""
    token, _ = _parse_profile_arg(arg(update))
    reply = update.message.reply_to_message if update.message else None
    if not reply or not reply.photo:
        await update.message.reply_text(
            "❌ Photo pe *reply* karke `~setbotpfp` bhejo.", parse_mode="Markdown"
        )
        return
    await _profile_entry(update, ctx, "pfp", reply.photo[-1].file_id, token)


async def cmd_setbotdescloop(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~setbotdescloop on 5m a | b / off — global rotating description."""
    if not update.message or update.effective_user.id != OWNER_ID:
        return
    if not is_main_bot(ctx):
        return
    raw = arg(update)
    parts = raw.split(None, 2)
    if not parts or parts[0].lower() not in ("on", "off"):
        await update.message.reply_text(
            "Usage: `~setbotdescloop on 5m desc 1 | desc 2` / `off`",
            parse_mode="Markdown",
        )
        return
    task = bot_description_loop_tasks.pop("global", None)
    if task and not task.done():
        task.cancel()
    if parts[0].lower() == "off":
        bot_description_loop_state.clear()
        save_feature_state()
        await update.message.reply_text(
            ui_card("👑 ɴɪᴋ ʙᴏᴛ · ᴅᴇsᴄ ʟᴏᴏᴘ", ["🔴 <b>ᴏꜰꜰ</b>"]),
            parse_mode="HTML",
        )
        return
    interval = parse_duration(parts[1]) if len(parts) > 1 else None
    descriptions_raw = parts[2] if len(parts) > 2 else ""
    descriptions = [x.strip()[:512] for x in descriptions_raw.split("|") if x.strip()]
    if not interval or not descriptions:
        await update.message.reply_text(
            "Example: `~setbotdescloop on 5m First bio | Second bio`",
            parse_mode="Markdown",
        )
        return
    bot_description_loop_state.update({"interval": interval, "descriptions": descriptions})
    bot_description_loop_tasks["global"] = asyncio.create_task(
        _bot_description_loop_worker(interval, descriptions)
    )
    save_feature_state()
    await update.message.reply_text(
        ui_card("👑 ɴɪᴋ ʙᴏᴛ · ᴅᴇsᴄ ʟᴏᴏᴘ", [
            "🟢 <b>ᴏɴ</b>",
            f"⏱ ʜᴀʀ <code>{_esc(format_remaining(interval))}</code>",
            f"📝 <b>{len(descriptions)}</b> ᴛᴇxᴛs",
            "🌐 ᴛᴀʀɢᴇᴛ : <b>ᴀʟʟ ʙᴏᴛs</b>",
        ]),
        parse_mode="HTML",
    )


async def handle_profile_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """DM bot-picker ke buttons."""
    query = update.callback_query
    if not query or not query.data:
        return
    uid = query.from_user.id
    if uid != OWNER_ID:
        await query.answer("Owner only", show_alert=True)
        return
    if not is_main_bot(ctx):
        await query.answer("Main bot only", show_alert=True)
        return
    st = _prof_pending.get(uid)
    if not st or time.time() - st["ts"] > _PROFILE_TTL:
        _prof_pending.pop(uid, None)
        await query.answer("⏰ Expired — command dobara bhejo", show_alert=True)
        return
    action = query.data[len("prof:"):]
    await query.answer()
    if action == "cancel":
        _prof_pending.pop(uid, None)
        try:
            await query.edit_message_text(
                ui_card("👑 ɴɪᴋ ʙᴏᴛ · ᴘʀᴏꜰɪʟᴇ ᴇɴɢɪɴᴇ", ["❌ <b>ᴄᴀɴᴄᴇʟʟᴇᴅ</b>"]),
                parse_mode="HTML", reply_markup=InlineKeyboardMarkup([]),
            )
        except Exception:
            pass
        return
    profiles = await _profile_choices()
    if action == "all":
        targets = [p["bot"] for p in profiles]
        label = "🌐 ᴀʟʟ ʙᴏᴛs"
    elif action.startswith("pick:"):
        try:
            bid = int(action.split(":", 1)[1])
        except ValueError:
            return
        p = next((x for x in profiles if x["id"] == bid), None)
        if p is None:
            await query.answer("Bot offline", show_alert=True)
            return
        targets = [p["bot"]]
        label = "@" + (p["username"] or str(p["id"]))
    else:
        return
    _prof_pending.pop(uid, None)
    try:
        await query.edit_message_text(
            "⚡ ...", parse_mode="HTML", reply_markup=InlineKeyboardMarkup([])
        )
    except Exception:
        pass
    await _profile_run(query.message, st["kind"], st["value"], targets, label)


async def handle_ui_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Advanced panel ke 🎬 UI / 🤖 profile buttons."""
    query = update.callback_query
    if not query or not query.data:
        return
    if not is_auth(query.from_user.id):
        await query.answer("Owner / Sudo only", show_alert=True)
        return
    if not is_main_bot(ctx):
        await query.answer("Main bot only", show_alert=True)
        return
    action = query.data[len("panel:"):]
    await query.answer()
    target = query.message
    if action == "ui":
        msg = await target.reply_text("⚡ ...", parse_mode="HTML")
        await _ui_dashboard(msg)
    elif action == "profile":
        profiles = await _profile_choices()
        rows = [
            f"🤖 ʟᴏᴀᴅᴇᴅ ʙᴏᴛs : <b>{len(profiles)}</b>",
            "",
            "<code>~setbotname &lt;txt&gt;</code> · ɴᴀᴍᴇ",
            "<code>~setbotbio &lt;txt&gt;</code> · sʜᴏʀᴛ ʙɪᴏ",
            "<code>~setbotdesc &lt;txt&gt;</code> · ʟᴏɴɢ ᴅᴇsᴄ",
            "<code>~setbotpfp</code> · ᴘʜᴏᴛᴏ ʀᴇᴘʟʏ",
            "",
            "📍 ɢʀᴏᴜᴘ → <b>ᴀʟʟ ʙᴏᴛs</b>",
            "📍 ᴅᴍ → <b>ᴘɪᴄᴋ ᴏɴᴇ</b> / <b>🌐 ᴀʟʟ</b>",
            "⚑ <code>--all</code> · <code>#2</code> · <code>@bot</code>",
        ]
        await target.reply_text(
            ui_card("👑 ɴɪᴋ ʙᴏᴛ · ᴘʀᴏꜰɪʟᴇ ʜᴜʙ", rows), parse_mode="HTML"
        )


def _register(app: Application) -> None:
    def h(pat: str, fn):
        return MessageHandler(
            filters.Regex(rf"(?i)^~{pat}(\s|$)") & filters.TEXT, fn
        )

    W = warfare_wrap   # shorthand

    # ── middleware · DM login (group=-3) → prefix gate (group=-2) ───────────
    app.add_handler(MessageHandler(filters.TEXT & filters.Regex(r"^[~/]"),
                                  main_bot_guard), group=-4)
    app.add_handler(MessageHandler(filters.TEXT & filters.ChatType.PRIVATE,
                                  handle_login_input), group=-3)
    app.add_handler(MessageHandler(filters.TEXT & filters.Regex(r"^~"),
                                  prefix_gate), group=-2)

    # ── Warfare commands — all wrapped with warfare_wrap ──────────────────────
    # warfare_wrap handles: (a) DM → broadcast to all known GCs
    #                       (b) MULTIMODE → broadcast to other known GCs after execution
    app.add_handler(h("nc",              W(cmd_nc)))
    app.add_handler(h("fucknc",          W(cmd_fucknc)))
    app.add_handler(h("ncloop",          W(cmd_ncloop)))
    app.add_handler(h("raidnc",          W(cmd_raidnc)))
    app.add_handler(h("timenc",          W(cmd_timenc)))
    app.add_handler(h("spam",            W(cmd_spam)))
    app.add_handler(h("Targetslide",     W(cmd_targetslide)))
    app.add_handler(h("picraid",         W(cmd_picraid)))
    app.add_handler(h("crashtextraid",   W(cmd_crashtextraid)))
    app.add_handler(h("stopnc",          W(cmd_stopnc)))
    app.add_handler(h("stopspam",        W(cmd_stopspam)))
    app.add_handler(h("stoptargetslide", W(cmd_stoptargetslide)))
    app.add_handler(h("stoppicraid",     W(cmd_stoppicraid)))
    app.add_handler(h("stopall",         W(cmd_stopall)))
    app.add_handler(h("spam1",           W(cmd_spam1)))
    app.add_handler(h("mute",            W(cmd_mute)))
    app.add_handler(h("unmute",          W(cmd_unmute)))
    app.add_handler(h("longnc",          W(cmd_longnc)))
    app.add_handler(h("crashnc",         W(cmd_crashnc)))
    app.add_handler(h("stopcrashnc",     W(cmd_stopcrashnc)))
    app.add_handler(h("glitchnc2",       W(cmd_glitchnc2)))
    app.add_handler(h("crashnc2",        W(cmd_crashnc2)))
    app.add_handler(h("stopcrashnc2",    W(cmd_stopcrashnc2)))
    app.add_handler(h("crashnc3",        W(cmd_crashnc3)))
    app.add_handler(h("stopcrashnc3",    W(cmd_stopcrashnc3)))
    app.add_handler(h("nc2",             W(cmd_nc2)))
    app.add_handler(h("aninc",           W(cmd_aninc)))
    app.add_handler(h("glitchnc",        W(cmd_glitchnc)))
    app.add_handler(h("swipe",           W(cmd_swipe)))
    app.add_handler(h("stopswipe",       W(cmd_stopswipe)))
    app.add_handler(h("ftnc",           W(cmd_ftnc)))
    app.add_handler(h("stopftnc",       W(cmd_stopftnc)))
    app.add_handler(h("glitchnc3",      W(cmd_glitchnc3)))
    app.add_handler(h("hnc",            W(cmd_hnc)))
    app.add_handler(h("inc",            W(cmd_inc)))
    app.add_handler(h("jnc",            W(cmd_jnc)))

    # ── Non-warfare commands — no wrap needed ─────────────────────────────────
    app.add_handler(h("setmenu",         cmd_setmenu))
    app.add_handler(h("setmenupic",      cmd_setmenu))
    app.add_handler(h("setmenuvid",      cmd_setmenuvid))
    app.add_handler(h("removemenupic",   cmd_removemenupic))
    app.add_handler(h("help",            cmd_help))
