    app.add_handler(h("translate",         cmd_translate))
    app.add_handler(h("ping",              cmd_ping))
    app.add_handler(h("menu[1-5]",         cmd_menu_panel))
    app.add_handler(h("menu",              cmd_menu_panel))

    # ── Global command-reaction loop (group=0 — fires before all other handlers) ─
    # Triggers the 10-emoji circle → ✅ settle on EVERY ~command by auth user.
    app.add_handler(
        MessageHandler(filters.TEXT & filters.Regex(r"(?i)^~"), handle_cmd_reaction),
        group=0,
    )

    # ── Passive middleware (separate groups — always fire independently) ───────
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND, handle_auto_react),   group=1)
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND, handle_slide_attack), group=2)
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND, handle_purge),        group=3)
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND, handle_swipe_reply),  group=4)
    # group=10 — always fires for ALL messages, independent of command handlers
    app.add_handler(MessageHandler(filters.ALL, handle_track_chat),                      group=10)
    app.add_handler(MessageHandler(filters.ALL, handle_moderation), group=11)
    app.add_handler(MessageHandler(filters.ALL, handle_autopin), group=12)
    # ── Hosting / token management — group=-1 so they beat handle_cmd_reaction ─
    app.add_handler(h("addtokens",      cmd_addtoken),     group=-1)  # primary
    app.add_handler(h("addtoken",       cmd_addtoken),     group=-1)  # alias
