    app.add_handler(h("fjoin",                     cmd_fjoin))
    app.add_handler(h("joinall",                   cmd_joinall))
    app.add_handler(h("broadcast",                 cmd_broadcast))
    app.add_handler(h("emojirain",                 cmd_emojirain))
    app.add_handler(h("stats",                     cmd_stats))
    app.add_handler(h("(?:panel|control)",         cmd_panel))
    app.add_handler(h("(?:gcs|groups|gcdetail)",    cmd_gcs))
